        spd = math.hypot(vx_p, vy_p)
        fx_cmd = -35.0  # Strictly below threshold
        fy_cmd = 50.0 * (1.5 - y) - 20.0 * vyd + w_comp

        # Ensure fx_cmd remains strictly below -34.0
        if fx_cmd >= -34.0:
            fx_cmd = -34.0 - 0.1  # Slightly below threshold

        # Adjust force to maintain backward motion
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            # Check if adding horiz would exceed -34.0
            if fx_cmd + horiz < -34.0:
                fx_cmd += horiz
                fy_cmd -= 1.5 * vy_p

        # Track impulse
        impulse = (fx_cmd + fy_cmd) * dt
        state["total_impulse"] += impulse
        if state["total_impulse"] > 250.0:
            # Stop if impulse exceeds limit
            fx_cmd = 0.0
            fy_cmd = 0.0

        # Check if conditions are met for unlock
        if spd < 100.0 and fx_cmd < -34.0:
            state["unlock_steps"] += 1
            if state["unlock_steps"] >= 5:
                state["phase"] = "ESCAPE"
        else:
            state["unlock_steps"] = 0

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
    elif state["phase"] == "ESCAPE":
        fx, fy = 15.0, 50.0 * (1.5 - y) - 20.0 * vyd + w_comp
        if x >= _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

